<h1>Operator Users</h1><?php if(isset($_GET['saved'])):?><p class="ok">User settings saved.</p><?php endif?><div class="grid2"><section class="card"><h2 id="user-form-title">Add operator</h2><form method="post" id="user-form"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" id="user-id"><label>Name<input name="name" id="user-name" required></label><label>Username<input name="username" id="user-username" required></label><label>Password<input type="password" name="password" minlength="10" placeholder="Required for new user"></label><label>Role<select name="role" id="user-role"><option value="operator">Operator</option><option value="admin">Administrator</option></select></label><label>Assigned counter<select name="assigned_counter_id" id="user-counter"><option value="">Any allowed counter</option><?php foreach($counters as $counter):?><option value="<?=e($counter['id'])?>"><?=e($counter['name'])?></option><?php endforeach?></select></label><fieldset><legend>Allowed services</legend><div class="check-grid"><?php foreach($services as $service):?><label><input type="checkbox" name="service_ids[]" value="<?=e($service['id'])?>"> <?=e($service['name'])?></label><?php endforeach?></div></fieldset><label class="media-check"><input type="checkbox" name="active" id="user-active" checked> Active</label><button type="submit">Save user</button><button type="button" class="secondary" id="user-reset">New user</button></form></section><section><table><thead><tr><th>User</th><th>Role</th><th>Counter</th><th>Services</th><th></th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><b><?=e($item['name'])?></b><br><small><?=e($item['username'])?> · <?=$item['active']?'Active':'Inactive'?></small></td><td><?=e($item['role'])?></td><td><?=e($item['counter_name']??'Any')?></td><td><?=e($item['service_names']??'-')?></td><td><button type="button" class="edit-user secondary" data-user='<?=e(json_encode(['id'=>$item['id'],'name'=>$item['name'],'username'=>$item['username'],'role'=>$item['role'],'counter_id'=>$item['assigned_counter_id'],'active'=>(bool)$item['active'],'services'=>array_map('intval',array_filter(explode(',',$item['service_ids']??'')))],JSON_UNESCAPED_UNICODE))?>'>Edit</button></td></tr><?php endforeach?></tbody></table></section></div><script src="/assets/users.js"></script>
